function ui_icon(string $name, string $class = ''): string
{
    $paths = ui_icon_paths()[$name] ?? '';
    if ($paths === '') {
        return '';
    }
    $classAttr = trim('ui-icon ' . $class);
    return '<svg class="' . htmlspecialchars($classAttr, ENT_QUOTES) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' . $paths . '</svg>';
}
